    private void filters(){if(Arrays.asList("all","animevost","animedia","kodik").contains(selectedSource)){new AlertDialog.Builder(this).setTitle("Поиск по названию").setMessage("Этот источник не предоставляет дополнительные фильтры. Введите название аниме в строке поиска.").setPositiveButton("Понятно",null).show();return;}LinearLayout c=Ui.column(this);c.setPadding(Ui.dp(this,24),Ui.dp(this,10),Ui.dp(this,24),Ui.dp(this,15));String[][] genreItems=genresFor(selectedSource);String[] genreLabels=new String[genreItems.length],genreIds=new String[genreItems.length];for(int gi=0;gi<genreItems.length;gi++){genreIds[gi]=genreItems[gi][0];genreLabels[gi]=genreItems[gi][1];}Spinner genre=spinner(c,"Жанр",genreLabels,Arrays.asList(genreIds).indexOf(filter.genre));ArrayList<String> ys=new ArrayList<>();ys.add("Все годы");for(int y=Calendar.getInstance().get(Calendar.YEAR)+1;y>=1970;y--)ys.add(String.valueOf(y));Spinner year=spinner(c,"Год",ys.toArray(new String[0]),filter.year.isEmpty()?0:ys.indexOf(filter.year));String[] kinds={"Любой формат","ТВ","Фильм","ONA","OVA","Спешл"},values={"","TV","MOVIE","ONA","OVA","SPECIAL"};Spinner type=spinner(c,"Формат",kinds,Arrays.asList(values).indexOf(filter.type));String[] statusLabels={"Любой статус","Выходит","Завершён","Анонс"},statusValues={"","ongoing","released","anons"};Spinner status=spinner(c,"Статус",statusLabels,Arrays.asList(statusValues).indexOf(filter.status));String[] sortLabels={"По рейтингу","Популярные","Сначала новые"},sortValues={"RATING_DESC","POPULARITY","YEAR_DESC"};Spinner sort=spinner(c,"Порядок",sortLabels,Arrays.asList(sortValues).indexOf(filter.sort));TextView note=Ui.text(this,(selectedSource.equals("animevost")||selectedSource.equals("animelib"))?"У этого источника часть фильтров может быть недоступна.":"",10,Ui.MUTED,false);c.addView(note);new AlertDialog.Builder(this).setTitle("Подберите историю").setView(c).setPositiveButton("Применить",(d,w)->{ApiRepository.Filter f=new ApiRepository.Filter();if(!selectedSource.equals("animevost")&&!selectedSource.equals("animelib")){f.genre=genreIds[genre.getSelectedItemPosition()];f.year=year.getSelectedItemPosition()==0?"":ys.get(year.getSelectedItemPosition());f.type=values[type.getSelectedItemPosition()];}if(!selectedSource.equals("animevost"))f.status=statusValues[status.getSelectedItemPosition()];f.sort=sortValues[sort.getSelectedItemPosition()];filter=f;loadCatalog(true);}).setNeutralButton("Сбросить",(d,w)->{filter=new ApiRepository.Filter();loadCatalog(true);}).setNegativeButton("Отмена",null).show();}
